package com.nivor.note;
import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;import java.util.*;
@Entity@Table(name="notes",indexes=@Index(name="idx_note_user",columnList="user_id"))public class Note extends AuditedEntity{
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(nullable=false,length=180)private String title;@Column(columnDefinition="TEXT")private String content;@Column(length=80)private String category;@ElementCollection@CollectionTable(name="note_tags",joinColumns=@JoinColumn(name="note_id"))@Column(name="tag",length=40)private List<String> tags=new ArrayList<>();private boolean favorite;private boolean pinned;
 protected Note(){}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public List<String> getTags(){return tags;}public void setTags(List<String> v){tags=v==null?new ArrayList<>():new ArrayList<>(v);}public boolean isFavorite(){return favorite;}public void setFavorite(boolean v){favorite=v;}public boolean isPinned(){return pinned;}public void setPinned(boolean v){pinned=v;}
}
